var seed = Math.random() * 1000;
var particles = [];
var mySize;
var parNum;
let colors1 = "e5463e-ef6a5b-bc3c34-1f6f36-498655-1e5c2e-416fd2-6b85da-3a5cac".split("-").map((a) => "#" + a);
let colors2 = "e183ce-e4d4ad-55e597-728581-f94f2e-6e467f-5a73d8-77d831-a2745d".split("-").map((a) => "#" + a);
let colors3 = "ff499e-d264b6-a480cf-779be7-49b6ff-49ffd4-f080d2-a3c48b-ccc792".split("-").map((a) => "#" + a);
let colors4 = "547cff-49a181-7691f9-d6e6e9-3e1b9f-de958c-3e8953-af5046-3d43ae".split("-").map((a) => "#" + a);
let colorbg = "1e2426".split("-").map((a) => "#" + a);
let timer = 0;
let fireworks_color;

function setup() {
	//randomSeed(seed);
	mySize = max(windowWidth, windowHeight);
	createCanvas(windowWidth, windowHeight);
	// createCanvas(600,600);
	// pixelDensity(5);
	background(colorbg);
	fireworks_color = random([colors1,colors2,colors3,colors4]);
	make_par(width / 2, height / 2);
	let filter = new makeFilter();
}

function make_par(x, y) {
	this.x = x;
	this.y = y;
	parNum = random([5,10]);
	for (let i = 0; i < parNum; i++) {
		particles.push(new Particle(this.x, this.y))
	}
}

function draw() {
	randomSeed(seed);
	// blendMode(ADD)
	for (let i = particles.length - 1; i > 0; i--) {
		if (i < particles.length) {
			particles[i].show();
			particles[i].update();
			if (particles[i].r < 5) {
				particles[i].explode();
			}
			if (particles[i].finished()) {
				if (timer < 50) {
					make_par(particles[i].x, particles[i].y);
					timer++;
				}
				particles.splice(i, 1);		
			}
		}

	}
	image(overAllTexture, 0, 0);
}

function makeFilter() {
	// noiseのフィルターをつくる
	colorMode(HSB, 360, 100, 100, 100);
	drawingContext.shadowColor = color(0, 0, 95, 25);
	overAllTexture = createGraphics(windowWidth, windowHeight);
	overAllTexture.loadPixels();
	for (var i = 0; i < width; i++) {
		for (var j = 0; j < height; j++) {
			overAllTexture.set(
				i,
				j,
				color(
					10,
					10,
					10,
					noise(i / 3, j / 3, (i * j) / 50) * random(1, 15)
				)
			);
		}
	}
	overAllTexture.updatePixels();
}

function mouseClicked(){
	//loop();
	particles = [];
	background(colorbg);
	fireworks_color = random([colors1,colors2,colors3,colors4]);
	make_par((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
	timer =0;
}

function keyTyped() {
	if (key === "s" || key === "S") {
		noLoop();
		saveCanvas("Xmas_Fireworks", "png");
	}
}

// === Tab: tab2 ===
function Particle(x, y) {
	this.x = x;
	this.y = y;
	this.pos = createVector(this.x, this.y);
	this.vel = createVector(0,-sin(random(0,1)));
	this.acc = createVector(random(0.01,-0.01), random(0.01,-0.01));
	//this.alpha = 100;
	this.r = random(30, 10);
	this.particles2 = [];
	this.color = random(fireworks_color);

	this.update = function() {
		this.vel.add(this.acc);
		this.pos.add(this.vel);
		//this.alpha -= 0.25;
		if (this.r > 0) {
			this.r -= 0.1;
		}
	};

	this.show = function() {
		fill(this.color);
		noStroke();
		circle(this.pos.x, this.pos.y, this.r);
	};

	this.explode = function() {
		this.particles2.push(new Particle2(this.pos.x, this.pos.y, this.r,this.color));
		for (let i = this.particles2.length - 1; i > 0; i--) {
			//this.particles2[i].r = this.r;
			this.particles2[i].show();
			this.particles2[i].update();

			if (this.particles2[i].finished()) {
				this.particles2.splice(i, 1);
			}
		}
	};

	this.finished = function() {
		return this.r < 3;
	};
}

// === Tab: tab3 ===
function Particle2(x, y,r,color) {
	this.x = x;
	this.y = y;
	this.explode = new Particle(this.x, this.y);
	this.pos = createVector(this.x, this.y);
	this.vel = createVector(random(-1.25,1.25), random(-1.25,1.25));
	this.acc = createVector(random(-0.005, 0.005), random(-0.005, 0.005));
	//this.alpha = 50;
	this.r = r;
	this.color = color;


	this.update = function() {
		this.vel.add(this.acc);
		this.pos.add(this.vel);
		if (this.r > 0) {
			this.r -= 0.01;
		}
	}

	this.show = function() {
		noFill();
		stroke(this.color);
		strokeWeight(random(1));
		circle(this.pos.x, this.pos.y, this.r);
	}

	this.finished = function() {
		return this.r < 0;
	};
}

